1	/**
2	 * The `int(str)` constructor and `str(int)` conversion, including the
3	 * interpreter's ceiling on decimal conversions.
4	 */
5	
6	import { PyInt } from './integer.mjs';
7	import { PyValueError } from './errors.mjs';
8	import { decimalDigitValue, isPyWhitespace } from './unicode-data.mjs';
9	import { pyRepr } from './repr.mjs';
10	
11	/** `sys.get_int_max_str_digits()` -- the interpreter default. */
12	export const MAX_STR_DIGITS = 4300;
13	
14	const LIMIT_MESSAGE =
15	  `Exceeds the limit (${MAX_STR_DIGITS} digits) for integer string conversion; ` +
16	  'use sys.set_int_max_str_digits() to increase the limit';
17	
18	/**
19	 * Parse text exactly as `int(text)` does for base 10:
20	 *
21	 *   - surrounding Unicode whitespace is discarded
22	 *   - an optional single '+' or '-' may follow, with no gap before the digits
23	 *   - digits are any Unicode decimal characters, mixed scripts allowed
24	 *   - single underscores are permitted between digits only
25	 *   - more than MAX_STR_DIGITS digits is refused outright
26	 *
27	 * @throws {PyValueError} on anything else.
28	 * @returns {PyInt}
29	 */
30	export function pyIntFromString(text) {
31	  const invalid = () =>
32	    new PyValueError(`invalid literal for int() with base 10: ${pyRepr(text)}`);
33	
34	  const chars = Array.from(text);
35	  let start = 0;
36	  let end = chars.length;
37	  while (start < end && isPyWhitespace(chars[start].codePointAt(0))) start++;
38	  while (end > start && isPyWhitespace(chars[end - 1].codePointAt(0))) end--;
39	
40	  let negative = false;
41	  if (start < end && (chars[start] === '+' || chars[start] === '-')) {
42	    negative = chars[start] === '-';
43	    start++;
44	  }
45	  if (start >= end) throw invalid();
46	
47	  let digits = '';
48	  let previousWasDigit = false;
49	  for (let i = start; i < end; i++) {
50	    const ch = chars[i];
51	    if (ch === '_') {
52	      // Separators need a digit on both sides, and may not be doubled.
53	      if (!previousWasDigit || i + 1 >= end) throw invalid();
54	      previousWasDigit = false;
55	      continue;
56	    }
57	    const value = decimalDigitValue(ch.codePointAt(0));
58	    if (value < 0) throw invalid();
59	    digits += String(value);
60	    previousWasDigit = true;
61	  }
62	  if (!previousWasDigit) throw invalid();
63	
64	  if (digits.length > MAX_STR_DIGITS) throw new PyValueError(LIMIT_MESSAGE);
65	  return PyInt.fromDigits(negative, digits);
66	}
67	
68	/**
69	 * `str(value)`, subject to the same decimal-conversion ceiling.
70	 * @throws {PyValueError} when the value is too wide to render.
71	 */
72	export function pyIntToString(value) {
73	  if (value.decimalLength() > MAX_STR_DIGITS) throw new PyValueError(LIMIT_MESSAGE);
74	  return value.toString();
75	}
