1	/**
2	 * Unicode tables required to reproduce CPython's `int(str)` acceptance rules.
3	 *
4	 * `int()` is far more permissive than an ASCII-only parser: it strips Unicode
5	 * whitespace and accepts any character in general category Nd, using that
6	 * character's decimal value.  Both tables below are static data, so no runtime
7	 * scanning (and no external dependency) is needed.
8	 */
9	
10	/**
11	 * Start code points of every ten-code-point decimal-digit run (category Nd).
12	 * A character `cp` in `[start, start + 9]` has decimal value `cp - start`.
13	 *
14	 * Derived by walking the full code space with the `\p{Nd}` property escape and
15	 * splitting each contiguous run into aligned groups of ten -- Unicode always
16	 * encodes a decimal digit set as ten consecutive code points.
17	 */
18	export const DECIMAL_DIGIT_RUN_STARTS = [
19	  0x0030, 0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66,
20	  0x0be6, 0x0c66, 0x0ce6, 0x0d66, 0x0de6, 0x0e50, 0x0ed0, 0x0f20, 0x1040,
21	  0x1090, 0x17e0, 0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0,
22	  0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0,
23	  0xff10, 0x104a0, 0x10d30, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0,
24	  0x11450, 0x114d0, 0x11650, 0x116c0, 0x11730, 0x118e0, 0x11950, 0x11c50,
25	  0x11d50, 0x11da0, 0x11f50, 0x16a60, 0x16ac0, 0x16b50, 0x1d7ce, 0x1d7d8,
26	  0x1d7e2, 0x1d7ec, 0x1d7f6, 0x1e140, 0x1e2f0, 0x1e4f0, 0x1e950, 0x1fbf0,
27	];
28	
29	/**
30	 * Code points CPython treats as whitespace when trimming a numeric literal
31	 * (`Py_UNICODE_ISSPACE`).  Ranges are inclusive `[lo, hi]` pairs.
32	 */
33	const WHITESPACE_RANGES = [
34	  [0x0009, 0x000d], [0x001c, 0x0020], [0x0085, 0x0085], [0x00a0, 0x00a0],
35	  [0x1680, 0x1680], [0x2000, 0x200a], [0x2028, 0x2029], [0x202f, 0x202f],
36	  [0x205f, 0x205f], [0x3000, 0x3000],
37	];
38	
39	/**
40	 * Decimal value of `cp`, or -1 when `cp` is not a decimal digit.
41	 * Binary search over the run table.
42	 */
43	export function decimalDigitValue(cp) {
44	  let lo = 0;
45	  let hi = DECIMAL_DIGIT_RUN_STARTS.length - 1;
46	  while (lo <= hi) {
47	    const mid = (lo + hi) >> 1;
48	    const start = DECIMAL_DIGIT_RUN_STARTS[mid];
49	    if (cp < start) {
50	      hi = mid - 1;
51	    } else if (cp > start + 9) {
52	      lo = mid + 1;
53	    } else {
54	      return cp - start;
55	    }
56	  }
57	  return -1;
58	}
59	
60	/** True when `cp` is stripped from the ends of a numeric literal. */
61	export function isPyWhitespace(cp) {
62	  for (const [lo, hi] of WHITESPACE_RANGES) {
63	    if (cp >= lo && cp <= hi) return true;
64	  }
65	  return false;
66	}
