68	/**
69	 * True when a character is printable in Python's sense, i.e. `str.isprintable`
70	 * -- everything except categories Cc, Cf, Cs, Co, Cn, Zl, Zp and Zs, with
71	 * U+0020 explicitly printable.  Used by `repr()` for CLI error messages.
72	 */
73	const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;
74	
75	export function isPyPrintable(ch) {
76	  if (ch === ' ') return true;
77	  return !NON_PRINTABLE.test(ch);
78	}
