1	/**
2	 * `repr()` for strings, matching CPython closely enough for CLI diagnostics.
3	 *
4	 * argparse embeds the offending value with `%r`, so the quoting and escaping
5	 * rules are observable in the program's stderr.
6	 */
7	
8	import { isPyPrintable } from './unicode-data.mjs';
9	
10	const HEX_DIGITS = '0123456789abcdef';
11	
12	function toHex(value, width) {
13	  let out = '';
14	  let rest = value;
15	  while (rest > 0) {
16	    out = HEX_DIGITS[rest % 16] + out;
17	    rest = Math.floor(rest / 16);
18	  }
19	  return out.padStart(width, '0');
20	}
21	
22	function escapeCodePoint(ch) {
23	  const cp = ch.codePointAt(0);
24	  if (cp < 0x100) return `\\x${toHex(cp, 2)}`;
25	  if (cp < 0x10000) return `\\u${toHex(cp, 4)}`;
26	  return `\\U${toHex(cp, 8)}`;
27	}
28	
29	/**
30	 * Render `value` the way `repr()` would: single quotes by default, double
31	 * quotes when the text contains a single quote but no double quote.
32	 */
33	export function pyRepr(value) {
34	  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
35	  let out = quote;
36	  for (const ch of value) {
37	    if (ch === '\\') {
38	      out += '\\\\';
39	    } else if (ch === quote) {
40	      out += `\\${ch}`;
41	    } else if (ch === '\n') {
42	      out += '\\n';
43	    } else if (ch === '\r') {
44	      out += '\\r';
45	    } else if (ch === '\t') {
46	      out += '\\t';
47	    } else if (isPyPrintable(ch)) {
48	      out += ch;
49	    } else {
50	      out += escapeCodePoint(ch);
51	    }
52	  }
53	  return out + quote;
54	}
